const ACHIEVEMENTS={"primer_quiz":{"icon":"🧠","label":"Primer quiz de la mesa superado"},"flash_master":{"icon":"🃏","label":"Todos los términos de la negociación explorados"},"clasif_pro":{"icon":"🗂️","label":"Clasificador de posición e interés experto"},"id_master":{"icon":"🔍","label":"Identificador de piezas de la mesa maestro"},"reto_hero":{"icon":"🏆","label":"Héroe del reto de los 30 segundos"},"sopa_champ":{"icon":"🔤","label":"Campeón de la sopa de la mesa"},"eval_ace":{"icon":"🎓","label":"Evaluación final aprobada con honores"},"full_xp":{"icon":"👑","label":"Etapa 3 de la Ruta del Poder Político completada"}};
function unlockAchievement(id){if(unlockedAch.includes(id))return;unlockedAch.push(id);sfx('ach');showToast(ACHIEVEMENTS[id].icon+' ¡Logro desbloqueado! '+ACHIEVEMENTS[id].label);launchConfetti();renderAchPanel();saveProgress();}
function renderAchPanel(){const list=document.getElementById('achList');list.innerHTML='';Object.entries(ACHIEVEMENTS).forEach(([id,a])=>{const div=document.createElement('div');div.className='ach-item'+(unlockedAch.includes(id)?'':' locked');div.innerHTML=`<span class="ach-icon">${a.icon}</span><span>${a.label}</span>`;list.appendChild(div);});}
