const enfermedadData=[{"disease":"Se acordó todo con un funcionario y al mes lo trasladaron","characteristic":"El acuerdo era con la persona y no con la institución, por escrito","opts":["El acuerdo era con la persona y no con la institución, por escrito","El nuevo funcionario tenía otra opinión","Faltó insistir más","El proyecto no era prioritario"]},{"disease":"Se bajó el precio en la reunión y después pidieron más cosas","characteristic":"Se cedió sin pedir nada a cambio, así que la línea se movió","opts":["Se cedió sin pedir nada a cambio, así que la línea se movió","El precio inicial era muy alto","Había demasiada gente en la sala","No se explicaron bien los costos"]},{"disease":"Pasaron cuatro meses esperando una respuesta que nunca llegó","characteristic":"Se tomó un «déjelo conmigo» por un sí y nadie puso fecha","opts":["Se tomó un «déjelo conmigo» por un sí y nadie puso fecha","La institución actuó de mala fe","Faltaba un documento","El correo se perdió"]},{"disease":"Usaron el material un año entero «de prueba» y nunca se firmó","characteristic":"El piloto no traía fecha de fin ni qué pasaba al terminar","opts":["El piloto no traía fecha de fin ni qué pasaba al terminar","El material gustó demasiado","Faltó cobrarles antes","No se hizo capacitación"]},{"disease":"Se aceptó un trato en el que no había ninguna moneda para el proyecto","characteristic":"Se fue a la mesa sin escribir qué se necesitaba de verdad","opts":["Se fue a la mesa sin escribir qué se necesitaba de verdad","La institución era demasiado grande","El proyecto no tenía experiencia","Faltó un abogado"]},{"disease":"Seis meses después dieron por incluido algo que nunca se habló","characteristic":"La minuta no decía qué quedaba fuera del acuerdo","opts":["La minuta no decía qué quedaba fuera del acuerdo","Se firmó demasiado rápido","Hubo mala intención","El acuerdo era muy largo"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

