const identifyTaskDB=[{"s":"Casi nunca puede decir sí, pero casi siempre puede decir no.","type":"Quien te recibe"},{"s":"Lo que la institución protege de verdad.","type":"El riesgo del funcionario"},{"s":"Lo que piden en voz alta.","type":"La posición"},{"s":"Para qué lo piden en realidad.","type":"El interés"},{"s":"Tu plan si te levantas de la mesa.","type":"Qué pasa si no hay trato"},{"s":"La línea que se decide en frío y en casa.","type":"El límite que no se cruza"},{"s":"Alcance, constancias, transporte e impresión.","type":"La moneda que no es dinero"},{"s":"Un centro, una sección, un mes.","type":"El piloto"},{"s":"Media hoja con quién hace qué y para cuándo.","type":"La minuta"},{"s":"«Déjelo conmigo», «estamos en eso».","type":"El sí que no es un sí"}];
const classifyTaskDB=[{"w":"«Lo queremos gratis»","gen":"Petición","n":"En voz alta","g":"Posición","t":"Lo que se dice"},{"w":"Enseñar algo en el informe anual","gen":"Petición","n":"Por debajo","g":"Interés","t":"Para qué lo piden"},{"w":"El límite que no se cruza","gen":"Preparación","n":"Antes","g":"Se lleva escrito","t":"Se decide en frío"},{"w":"Decidir el precio en la sala","gen":"Preparación","n":"En caliente","g":"Se improvisa","t":"Casi siempre sale caro"},{"w":"Constancia del distrito","gen":"Pago","n":"Real","g":"Moneda","t":"Se puede enseñar"},{"w":"«Visibilidad» sin decir dónde","gen":"Pago","n":"Vago","g":"Humo","t":"No se puede cobrar"},{"w":"Minuta el mismo día","gen":"Cierre","n":"Escrito","g":"Cierra","t":"Fija lo acordado"},{"w":"«Déjelo conmigo»","gen":"Cierre","n":"Verbal","g":"Queda abierto","t":"Ni sí ni no"},{"w":"Un piloto de un mes","gen":"Alcance","n":"Pequeño","g":"Baja el riesgo","t":"Crea un hecho"},{"w":"Un convenio para el departamento","gen":"Alcance","n":"Grande","g":"Sube el riesgo","t":"Tarda y se atasca"}];
const completeTaskDB=[{"s":"Lo que piden en voz alta es la ___.","opts":["posición","minuta","moneda"],"ans":"posición"},{"s":"Para qué lo piden es el ___.","opts":["interés","aval","plazo"],"ans":"interés"},{"s":"Lo que haces si no hay trato es tu ___.","opts":["alternativa","condición","excusa"],"ans":"alternativa"},{"s":"La línea que se decide en frío es el ___.","opts":["límite","precio","informe"],"ans":"límite"},{"s":"Constancias y transporte son ___ que no es dinero.","opts":["moneda","favor","trámite"],"ans":"moneda"},{"s":"Un mes en una sección es un ___.","opts":["piloto","aval","censo"],"ans":"piloto"},{"s":"El papel del mismo día es la ___.","opts":["minuta","factura","boleta"],"ans":"minuta"},{"s":"La institución protege el ___ de quien firma.","opts":["riesgo","sueldo","puesto"],"ans":"riesgo"}];
const explainQuestions=[{"q":"Explica la diferencia entre posición e interés, con el caso de la institución que pide las misiones gratis para el departamento.","ans":"La posición es lo que dicen en voz alta: «queremos las misiones gratis para todos los centros del departamento». El interés es para qué lo quieren, y casi nunca coincide: suele ser poder enseñar algo hecho en el informe de fin de año, o cumplir una meta que le pusieron a quien te recibe. Eso cambia la conversación entera, porque a la posición solo se puede decir sí o no, y al interés se le pueden ofrecer dos o tres salidas. Un piloto en tres centros, con constancia del distrito y con datos agregados para el informe, cubre el interés completo y no regala el trabajo de un año. La pregunta que abre esto es corta y hay que hacerla antes de proponer nada: «¿para qué lo necesitan?»."},{"q":"¿Qué es «qué pasa si no hay trato» y por qué es lo que de verdad da fuerza en una mesa?","ans":"Es tu plan si te levantas: qué haces con tu tiempo, con tu material y con tu año escolar si esa conversación no termina en nada. Se escribe antes de sentarse, en casa y en frío. Da fuerza porque quien no tiene a dónde ir acepta cualquier cosa, y eso se nota en la mesa aunque nadie lo diga: se nota en que aceptas plazos imposibles, en que bajas el precio sin que te lo pidan dos veces y en que contestas que sí en caliente. Al revés, quien tiene escrito que puede seguir con dos centros por su cuenta negocia tranquilo, y esa tranquilidad vale más que cualquier argumento. Además obliga a mirar algo incómodo y útil: a veces el plan sin trato es mejor que el trato que están ofreciendo."},{"q":"La institución dice que no tiene presupuesto. ¿Qué monedas se pueden pedir y cómo se piden?","ans":"Casi nunca hay dinero y casi siempre hay otras monedas, que se piden igual de concretas que un precio: la constancia firmada por el distrito, que sirve para todas las puertas siguientes; el transporte y los viáticos de la capacitación, que son gasto real; la impresión de las fichas, que ellos tienen y el proyecto no; el acceso a directores, con una carta de presentación a personas con nombre; y horas de capacitación pagadas dentro de la jornada. La regla para distinguir moneda de humo es simple: una moneda se puede escribir con número, con fecha y con nombre. «Visibilidad», «le abre puertas» y «le vamos a recomendar» no se pueden escribir así, así que no son pago: son una forma amable de pedir el trabajo gratis."},{"q":"¿Qué es el sí que no es un sí, cuánto cuesta y cómo se corta?","ans":"Es el «vamos a verlo», el «déjelo conmigo» y el «estamos en eso». La institución casi nunca dice que no, porque decir que no cuesta y callar no cuesta nada: simplemente deja de contestar. El daño no es la negativa, es el tiempo: se pierden tres o cuatro meses esperando algo que nunca fue un sí, y en un proyecto con año escolar eso puede ser la mitad de la oportunidad. Se corta poniendo fecha en la propia reunión, en voz alta y sin sonar a amenaza: «te llamo el 15, y si para entonces no hay respuesta lo entiendo como que este año no se puede y seguimos con los centros que ya tenemos». Eso convierte el silencio en una respuesta, que es todo lo que hacía falta."},{"q":"Explica por qué un piloto es mejor que un acuerdo grande, y qué tiene que traer escrito.","ans":"Un acuerdo grande obliga a quien firma a asumir un riesgo que nadie le va a agradecer si sale bien y que le van a cobrar si sale mal, así que su reacción natural es aplazar. Un piloto (un centro, una sección, un mes) baja ese riesgo casi a cero y además crea un hecho: al mes siguiente ya no se discute una idea, se discute algo que pasó, con datos. Pero un piloto sin escribir se convierte en la trampa contraria: se usa el material un año entero «de prueba» y nunca se firma nada. Por eso tiene que traer cuatro cosas por escrito: qué incluye, cuándo termina, cómo se mide si funcionó y qué pasa el día siguiente de que termine, con las dos opciones nombradas, la de seguir y la de parar."},{"q":"¿Qué es la minuta, qué lleva y por qué la escribe siempre uno mismo?","ans":"La minuta es media hoja enviada el mismo día que dice qué se acordó, quién hace qué, para cuándo, y también qué quedó fuera. La escribe uno mismo por una razón práctica: quien escribe la minuta fija lo que pasó, y casi nadie se molesta en escribirla, así que la versión que queda es la tuya. Lo que quedó fuera es la parte que más se olvida y la que más problemas evita: sin ella, dentro de seis meses alguien da por incluido algo que nunca se habló y ya no hay manera de discutirlo. Se manda a quien estuvo en la reunión y con copia a quien decide, y se pide una confirmación aunque sea de una línea. Y todo va a nombre de la institución, no de la persona: la institución no recuerda, cambia el funcionario y empieza de cero."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

