const evalTFBank=[{"q":"En una institución, quien te recibe casi siempre puede decir sí.","a":false},{"q":"Lo que la institución protege de verdad es que no le caiga un problema a quien firma.","a":true},{"q":"La posición es lo que piden y el interés es para qué lo piden.","a":true},{"q":"A una posición se le puede ofrecer más de una salida distinta.","a":false},{"q":"Tener escrito qué haces si no hay trato es lo que más fuerza da en una mesa.","a":true},{"q":"Ceder algo sin pedir nada a cambio enseña buena voluntad y ayuda al acuerdo.","a":false},{"q":"Cuando no hay presupuesto, casi siempre hay otras monedas que se pueden pedir.","a":true},{"q":"«Visibilidad» y «le abre puertas» son formas de pago que se pueden escribir.","a":false},{"q":"Un piloto baja el riesgo de quien firma y crea un hecho para la siguiente conversación.","a":true},{"q":"Un piloto sin fecha de fin puede convertirse en un año de uso sin firmar nada.","a":true},{"q":"«Déjelo conmigo» equivale a un sí mientras no digan lo contrario.","a":false},{"q":"La minuta la escribe quien convocó la reunión.","a":false},{"q":"En la minuta también se escribe lo que quedó fuera del acuerdo.","a":true},{"q":"Si cambian al funcionario, un acuerdo escrito a nombre de la institución sigue en pie.","a":true},{"q":"Lo difícil de una negociación se resuelve mejor con mucha gente en la sala.","a":false}];
