function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"La dirección departamental convoca a una mesa: quieren las misiones para todos los centros del departamento, sin costo, y piden empezar el mes que viene. Quien preside la reunión no puede firmar convenios."},{"txt":"Al terminar una reunión que fue muy bien, el funcionario dice «déjelo conmigo, yo lo muevo». Han pasado tres meses y no hay respuesta a dos correos."},{"txt":"En una reunión con seis personas de la institución, el que la preside pide delante de todos que se baje el precio de 150 lempiras por aula al mes a la mitad."},{"txt":"Ofrecen adoptar las misiones para el departamento a cambio de que el material salga a nombre de la institución y sin el nombre del autor."},{"txt":"La alcaldía ofrece imprimir 5.000 fichas si el logotipo va en la portada. Hay elecciones municipales en ocho meses."},{"txt":"Un centro lleva un año usando las misiones «de prueba». Nunca se firmó nada, nadie ha pagado y el director habla del proyecto como si ya fuera suyo."},{"txt":"Trasladan al funcionario con el que se acordó todo. El nuevo pide que se le explique el proyecto desde el principio y no encuentra ningún papel del acuerdo anterior."},{"txt":"Ponen como condición para dar el aval que la aplicación se aloje en el servidor de la institución y que ellos administren los datos de los estudiantes."}];
const critCaseQuestions=["1. ¿Cuál es la posición y cuál es el interés que hay debajo?","2. ¿Quién puede firmar esto, y qué riesgo está protegiendo?","3. Escribe en 3-4 frases lo que propones, con el piloto y la moneda que pides a cambio.","4. ¿Cuál es tu límite, qué haces si no hay trato y qué va en la minuta?"];
const critCaseGuides=["La posición es lo que se dijo en voz alta; el interés casi nunca coincide y suele ser enseñar algo hecho, cumplir una meta o no cargar con un riesgo.","Quien recibe casi nunca firma. Y lo que se protege no es el presupuesto: es que a quien firme no le caiga después un problema que nadie le va a agradecer haber evitado.","Casi ninguna mesa se cierra entera: se cierra un pedazo pequeño y pronto. El piloto es la herramienta, y la moneda se pide en la misma frase, no después.","Sin límite escrito, sin alternativa y sin minuta no hubo negociación: hubo una conversación agradable de la que cada uno salió con una idea distinta."];

const critErrorBank=[{"txt":"\"Como no tienen presupuesto, se lo damos gratis este año y el otro ya veremos\".","g1":"Regalar el primer año fija el precio de todos los siguientes: lo que se dio gratis una vez pasa a ser lo normal, y pedir dinero después parece un cambio de condiciones.","g2":"Se cobra en otra moneda desde el primer día: constancia del distrito, transporte de la capacitación, impresión pagada. Y se escribe qué pasa al terminar el año."},{"txt":"\"Bajo el precio ahora para que se vea buena voluntad y luego pido algo\".","g1":"Una cesión suelta mueve la línea y no compra nada: la siguiente conversación empieza desde el precio nuevo, y encima se espera otra cesión.","g2":"Cada cesión lleva pegada una condición en la misma frase: «puedo bajar a 100 si el acuerdo pasa de un año a tres y lo firma el distrito»."},{"txt":"\"Me dijo que lo dejara con él, así que está encaminado\".","g1":"«Déjelo conmigo» no es un sí ni un no, y como callar no le cuesta nada a la institución, el silencio puede durar meses.","g2":"Se pone fecha en la propia reunión, en voz alta: «te llamo el 15, y si no hay respuesta lo entiendo como que este año no se puede»."},{"txt":"\"El piloto va bien, mejor no molestar con papeles ahora\".","g1":"Un piloto sin fecha de fin se convierte en un año de uso gratis, y cuanto más dura, más difícil es cobrar por algo que ya se estaba dando.","g2":"El piloto se escribe antes de empezar: qué incluye, cuándo termina, cómo se mide y qué pasa el día siguiente, con las dos opciones nombradas."},{"txt":"\"El acuerdo lo tengo con el licenciado, que es muy accesible\".","g1":"La institución no recuerda: si lo trasladan, el acuerdo se va con él y el que llega no tiene ninguna obligación de sostener lo que no está escrito.","g2":"Todo a nombre de la institución, por escrito, con copia a quien decide, y una minuta por reunión aunque parezca exagerado."},{"txt":"\"Nos piden el nombre del autor fuera, pero a cambio entramos a todo el departamento\".","g1":"La autoría es de las pocas cosas que no vuelven: una vez que el material circula sin nombre, recuperarlo exige una pelea que no se puede ganar.","g2":"Ese es un límite que se decide en frío y en casa. Se acepta el alcance, se cede el logotipo si hace falta, y el nombre del autor se queda, que además no le cuesta nada a la institución."}];

const critDecisionBank=["La dirección departamental quiere las misiones para todos los centros sin costo: ¿qué propones y con qué piloto?","Llevan tres meses con «déjelo conmigo»: ¿qué haces, y qué dices exactamente para cortar el silencio?","Piden bajar el precio delante de seis personas: ¿qué contestas ahí y qué mandas después?","Ofrecen alcance a cambio de que el material salga sin el nombre del autor: ¿qué se cede y qué no?","La alcaldía imprime 5.000 fichas con su logotipo y hay elecciones en ocho meses: ¿se acepta y con qué condición?","Un centro lleva un año «de prueba» sin firmar nada: ¿cómo se cierra sin romper la relación?","Trasladaron al funcionario y el nuevo pide empezar de cero: ¿qué se enseña y qué se pide?","Condicionan el aval a alojar la aplicación en su servidor y administrar los datos: ¿qué se contesta?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se separa la posición del interés, porque a la posición solo se puede decir sí o no y al interés se le pueden ofrecer dos o tres salidas; después se mira quién decide de verdad y qué riesgo está protegiendo, que casi nunca es el presupuesto; después se propone un piloto pequeño y pronto en vez del acuerdo grande, y se pide la moneda en la misma frase en que se cede algo; y al final se cierra con minuta el mismo día, a nombre de la institución y con lo que quedó fuera escrito. Si al salir de la reunión no hay fecha ni papel, no hubo acuerdo: hubo una conversación agradable.';

const critCompareBank=[{"a":"Un piloto de un mes en tres centros, con fecha de fin escrita.","b":"Un convenio para todo el departamento, firmado más adelante.","ga":"Caso A: baja el riesgo de quien firma casi a cero y crea un hecho con datos para la siguiente conversación.","gb":"Caso B: obliga a asumir un riesgo que nadie agradece si sale bien, así que la reacción natural es aplazarlo."},{"a":"«Puedo bajar a 100 si el acuerdo pasa de uno a tres años».","b":"«Se lo dejo en 100 para que se vea la buena voluntad».","ga":"Caso A: cambia una cosa por otra, que es lo que se hace en una mesa, y deja el precio explicado.","gb":"Caso B: mueve la línea sin comprar nada, y la próxima conversación empieza en 100 esperando otra rebaja."},{"a":"«Te llamo el 15; si no hay respuesta, este año seguimos con los centros que ya tenemos».","b":"«Quedo pendiente de lo que me digan».","ga":"Caso A: convierte el silencio en una respuesta y pone el calendario de tu lado sin sonar a amenaza.","gb":"Caso B: deja el reloj en manos de quien no tiene ninguna prisa, y tres meses después no ha pasado nada."},{"a":"Minuta de media hoja, a nombre de la institución, con lo que quedó fuera.","b":"Un apretón de manos con el funcionario que impulsa el proyecto.","ga":"Caso A: sobrevive a un traslado y evita que dentro de seis meses se dé por incluido lo que nunca se habló.","gb":"Caso B: se va con la persona el día que la cambien, y no queda nada que enseñarle al que llega."}];

const critCauseBank=[{"cause":"Se va a la mesa sin saber quién decide.","guide":"Se negocia durante horas con alguien que no puede decir sí, y todo lo acordado tiene que volver a explicarse desde el principio a quien sí firma."},{"cause":"Se contesta a la posición y no al interés.","guide":"La conversación queda reducida a sí o no sobre lo que ellos propusieron, cuando había dos o tres salidas que cubrían lo que de verdad necesitaban."},{"cause":"Se cede algo sin pedir nada a cambio.","guide":"La línea se mueve, no se compra nada, y la siguiente reunión empieza desde la posición nueva esperando otra cesión."},{"cause":"Se toma un «déjelo conmigo» por un sí.","guide":"Pasan meses sin respuesta y sin daño aparente, hasta que se acaba el año escolar y la oportunidad se fue con él."},{"cause":"El piloto empieza sin fecha de fin escrita.","guide":"Se convierte en un año de uso gratis, y cuanto más dura, más difícil resulta cobrar por algo que ya se estaba dando."},{"cause":"El acuerdo está a nombre de la persona, no de la institución.","guide":"Un traslado lo borra entero, y el funcionario que llega no tiene ninguna obligación de sostener lo que no está escrito."}];
const critEffectBank=[{"effect":"El acuerdo sobrevivió a un cambio de funcionario.","guide":"Estaba por escrito, a nombre de la institución y con copia a quien decide, así que el nuevo encontró el expediente hecho."},{"effect":"Se cerró un piloto en tres centros en la misma reunión.","guide":"Era pequeño y pronto, así que quien presidía sí podía autorizarlo sin pedir permiso a nadie."},{"effect":"La rebaja de precio vino acompañada de tres años de acuerdo.","guide":"La cesión llevaba pegada su condición en la misma frase, así que no se regaló nada: se cambió una cosa por otra."},{"effect":"Un silencio de tres meses se resolvió en una semana.","guide":"Había una fecha dicha en voz alta y una consecuencia clara, así que callar dejó de ser gratis."},{"effect":"El proyecto entró al departamento y el autor siguió apareciendo.","guide":"El nombre del autor estaba en el límite escrito en frío, y ceder el logotipo institucional cubrió el interés real sin tocarlo."},{"effect":"Nadie dio por incluido después lo que nunca se habló.","guide":"La minuta traía escrito lo que quedaba fuera, que es la parte que casi nadie escribe y la que más discusiones evita."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🤝 La mesa que se cierra · Forma ${cf} · La mesa · Ruta del Poder Político`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Cuál es el interés que hay debajo, quién decide de verdad y qué piloto propones con la moneda que pides a cambio? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La mesa que se cierra: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Cuál es el interés que hay debajo, quién decide de verdad y qué piloto propones con la moneda que pides a cambio? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La mesa que se cierra La mesa · Ruta del Poder Político · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La mesa que se cierra · La mesa · Ruta del Poder Político · Etapa 3 · Poder Político</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La mesa que se cierra · La mesa · Ruta del Poder Político · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

