const timelineData=[{"y":"1","icon":"🪑","label":"Quién está enfrente","text":"Si <strong>decide, traba o solo transmite</strong>. <strong>Decide:</strong> qué se puede cerrar hoy. <strong>Se rompe:</strong> al negociar horas con quien no puede firmar. <strong>En M.E.T.A.S:</strong> el director autoriza su centro; el departamento necesita otra firma."},{"y":"2","icon":"🛡️","label":"Qué protege","text":"El <strong>riesgo de quien firma</strong>, no el presupuesto. <strong>Decide:</strong> por qué te dicen que no. <strong>Se rompe:</strong> al confundir burocracia con desinterés. <strong>En M.E.T.A.S:</strong> nadie premia al que autorizó algo que salió bien, y sí se le cobra si sale mal."},{"y":"3","icon":"🎯","label":"Posición e interés","text":"Lo que piden y <strong>para qué lo piden</strong>. <strong>Decide:</strong> cuántas salidas hay. <strong>Se rompe:</strong> al contestar a la posición. <strong>En M.E.T.A.S:</strong> «las misiones gratis» suele ser «algo que enseñar en el informe»."},{"y":"4","icon":"🪙","label":"La moneda","text":"Alcance, constancias, transporte, impresión, acceso. <strong>Decide:</strong> si se puede cerrar sin presupuesto. <strong>Se rompe:</strong> al aceptar «visibilidad». <strong>En M.E.T.A.S:</strong> una constancia del distrito abre las diez puertas siguientes."},{"y":"5","icon":"⛔","label":"El límite","text":"La línea decidida <strong>en frío y en casa</strong>. <strong>Decide:</strong> cuándo levantarse. <strong>Se rompe:</strong> en la sala, donde ceder un poco siempre parece razonable. <strong>En M.E.T.A.S:</strong> el nombre del autor, los datos de menores y el criterio pedagógico."},{"y":"6","icon":"🌱","label":"El piloto","text":"Un sí grande convertido en <strong>uno pequeño y pronto</strong>. <strong>Decide:</strong> si hoy sale algo. <strong>Se rompe:</strong> sin fecha de fin, cuando se vuelve un año gratis. <strong>En M.E.T.A.S:</strong> un centro, una sección, un mes."},{"y":"7","icon":"📝","label":"El cierre","text":"La <strong>minuta del mismo día</strong>, con lo acordado y lo que quedó fuera. <strong>Decide:</strong> si el acuerdo existe. <strong>Se rompe:</strong> con el apretón de manos. <strong>En M.E.T.A.S:</strong> a nombre de la institución, porque el funcionario cambia."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(pusisteFecha){sfx(pusisteFecha?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(pusisteFecha){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📅</span><span class="ms-text"><strong>Pusiste fecha en voz alta:</strong> «te llamo el 15, y si no hay respuesta lo entiendo como que este año no se puede». Nadie se ofendió: callar dejó de ser gratis, que es lo único que hacía falta.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🌱</span><span class="ms-text"><strong>Y salió un piloto:</strong> el día 12 llamaron ellos para ofrecer tres centros y un mes, que era justo lo que quien te recibió sí podía autorizar sin pedirle permiso a nadie.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">😶</span><span class="ms-text"><strong>Te quedaste esperando:</strong> el «déjelo conmigo» sonaba a que estaba encaminado, así que solo tocaba tener paciencia y no molestar.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📆</span><span class="ms-text"><strong>Y se fue el año escolar:</strong> cuatro meses de espera, dos correos sin contestar y ninguna negativa. La institución no dijo que no: dejó de contestar, que le cuesta menos y hace el mismo daño.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"enfrente":{"nombre":"Quién está enfrente","icon":"🪑","estructura":{"title":"Qué es","info":"• Saber si quien te recibe <strong>decide, traba o transmite</strong><br>• Casi nunca puede decir sí, casi siempre puede decir no<br>• Y detrás hay alguien que firma y que no está en la sala"},"funcion":{"title":"Cómo se prepara","info":"• Se pregunta antes: <strong>«¿quién firma esto?»</strong><br>• Se averigua qué meta le pusieron a esa persona este año<br>• Y se lleva algo que <strong>esa persona sí pueda autorizar hoy</strong>"},"enfermedades":{"title":"Dónde se rompe","info":"• Al negociar dos horas con quien no puede firmar<br>• Al confundir simpatía con capacidad de decidir<br>• Al saltarse a quien traba, que después lo cobra"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Un <strong>director</strong> autoriza su centro y puede decidirlo en la reunión<br>• El <strong>distrito</strong> abre varios centros pero tarda<br>• La <strong>Secretaría</strong> da alcance y nunca decide en una sola mesa"}},"moneda":{"nombre":"La moneda que no es dinero","icon":"🪙","estructura":{"title":"Qué es","info":"• Todo lo que la institución <strong>sí tiene</strong> aunque no tenga presupuesto<br>• Constancias, transporte, impresión, horas pagadas, acceso<br>• Se pide igual de concreta que un precio"},"funcion":{"title":"Cómo se prepara","info":"• Se llevan <strong>tres monedas escritas</strong>, en orden de lo que más sirve<br>• Se pide en la misma frase en que se cede algo<br>• Prueba: una moneda se escribe con <strong>número, fecha y nombre</strong>"},"enfermedades":{"title":"Dónde se rompe","info":"• Al aceptar «visibilidad» y «le abre puertas», que no se pueden cobrar<br>• Al regalar el primer año «para entrar»<br>• Al pedir la moneda después de haber cedido"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• La que más vale hoy: una <strong>constancia firmada por el distrito</strong>, que abre las puertas siguientes<br>• Y la impresión pagada, que es gasto real del proyecto y ellos ya tienen"}},"limite":{"nombre":"El límite que no se cruza","icon":"⛔","estructura":{"title":"Qué es","info":"• La línea escrita <strong>en frío y en casa</strong>, antes de sentarse<br>• Va junto a «qué pasa si no hay trato»<br>• No es una postura dura: es lo que evita decidirlo con gente delante"},"funcion":{"title":"Cómo se prepara","info":"• Se escriben <strong>tres cosas que no se ceden</strong> y por qué<br>• Se escribe la alternativa: qué haces si te levantas<br>• Y se lee otra vez la mañana de la reunión"},"enfermedades":{"title":"Dónde se rompe","info":"• En la mesa pública, donde ceder un poco siempre parece razonable<br>• Con el «total, es solo esta vez»<br>• Cuando hay prisa: el que tiene prisa paga más"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Los tres de esta casa: el <strong>nombre del autor</strong>, los <strong>datos de menores</strong> y el <strong>criterio pedagógico</strong><br>• El logotipo institucional sí se cede; la autoría no vuelve"}},"cierre":{"nombre":"El cierre por escrito","icon":"📝","estructura":{"title":"Qué es","info":"• Media hoja el <strong>mismo día</strong>: qué se acordó, quién hace qué, para cuándo<br>• Y <strong>lo que quedó fuera</strong>, que es lo que casi nadie escribe<br>• A nombre de la institución, no de la persona"},"funcion":{"title":"Cómo se prepara","info":"• La escribe uno mismo: <strong>quien escribe la minuta fija lo que pasó</strong><br>• Se manda a quien estuvo, con copia a quien decide<br>• Se pide una confirmación, aunque sea de una línea"},"enfermedades":{"title":"Dónde se rompe","info":"• Con el apretón de manos y el «ya nos comunicamos»<br>• Al no poner fecha, que deja el reloj en manos de quien no tiene prisa<br>• Al dejar fuera lo que quedó fuera"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Es la misma disciplina del <strong>expediente</strong> de la etapa 2: lo que no está escrito, no pasó<br>• Y la razón de fondo: <strong>la institución no recuerda</strong>, cambia el funcionario y se empieza de cero"}}};
let labParte='enfrente',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🤝 ¡'+name+' completó la Etapa 3 de la Ruta del Poder Político (La mesa)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

